package practice;

import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The name of a span attribute in the tracing library. Every span the service records asks for
 * the keys of its attributes, many thousands of times a second, from many threads.
 */
public final class AttributeKey {

    /** The attribute names the library defines; nearly every span uses them. */
    static final List<String> STANDARD = List.of("db.system", "http.route", "net.peer.port", "service.name");

    /** The keys this class keeps for reuse. */
    private static final Map<String, AttributeKey> KEYS = new ConcurrentHashMap<>();

    private final String name;

    private AttributeKey(String name) {
        this.name = name;
    }

    /** The key for an attribute name. */
    public static AttributeKey of(String name) {
        if (STANDARD.contains(name)) return KEYS.computeIfAbsent(name, AttributeKey::new);
        return new AttributeKey(name);
    }

    public String name() {
        return name;
    }

    /** How many keys this class is keeping for reuse. */
    static int kept() {
        return KEYS.size();
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof AttributeKey other && other.name.equals(name);
    }

    @Override
    public int hashCode() {
        return name.hashCode();
    }

    @Override
    public String toString() {
        return name;
    }
}

package practice;

import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            AttributeKey route = AttributeKey.of(new String("http.route".toCharArray()));
            AttributeKey routeAgain = AttributeKey.of(new String("http.route".toCharArray()));
            System.out.println("http.route key: " + route.name());
            System.out.println("same http.route object: " + (route == routeAgain));
            AttributeKey custom = AttributeKey.of("basket.items");
            System.out.println("custom key: " + custom.name() + ", equal to another: " + custom.equals(AttributeKey.of("basket.items")));
            for (int i = 0; i < 500; i++) AttributeKey.of("session-" + i);
            System.out.println("keys kept after 500 one-off names: " + AttributeKey.kept());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

